def smallest_number_for_pattern(pattern):
    answer=[];stack=[]
    for index in range(len(pattern)+1):
        stack.append(str(index+1))
        if index==len(pattern) or pattern[index]=='I':
            while stack:answer.append(stack.pop())
    return ''.join(answer)

